import json, os
d = json.load(open(os.path.expanduser("~/.claude.json")))
def find(obj, path=""):
    hits=[]
    if isinstance(obj, dict):
        for k,v in obj.items():
            if k.lower() in ("schedule","scheduledtasks","routines","cron","cronexpression","nextrun"):
                hits.append((path+"/"+k, type(v).__name__))
            hits+=find(v, path+"/"+k)
    elif isinstance(obj, list):
        for i,v in enumerate(obj[:3]):
            hits+=find(v, path+f"/[{i}]")
    return hits
for p,t in find(d): print(p, "->", t)
